// Safe to re-run after `pnpm start`: secrets already in the generated files keep their values (https://github.com/TheLinc/cover-me/commit/f2256d02).

import { randomBytes } from 'node:crypto'
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { BACKEND, REPO, localStatus, publishableKey, serviceKey } from './lib.mjs'

const status = localStatus()
const API_URL = status.API_URL

function readEnv(path) {
  if (!existsSync(path)) return {}
  const out = {}
  for (const line of readFileSync(path, 'utf8').split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=(.*)$/)
    if (m) out[m[1]] = m[2]
  }
  return out
}

function write(path, lines) {
  writeFileSync(path, lines.join('\n') + '\n')
  console.log(`wrote ${path.slice(REPO.length + 1)}`)
}

const fnPath = join(BACKEND, 'supabase', 'functions', '.env')
const fnOld = readEnv(fnPath)
const STRIPE_FN_KEYS = ['STRIPE_SECRET_KEY', 'STRIPE_PRO_PRICE_ID', 'STRIPE_PRO_QUARTERLY_PRICE_ID']
const anthropicKey = fnOld.ANTHROPIC_API_KEY || process.env.ANTHROPIC_API_KEY || ''
const keep = (name) => (fnOld[name] ? `${name}=${fnOld[name]}` : `# ${name}=`)
write(fnPath, [
  '# Local Edge Function secrets. Generated by `pnpm env:local`; gitignored.',
  '# SUPABASE_URL is injected by `supabase functions serve`.',
  `SERVICE_KEY=${serviceKey(status)}`,
  `ENCRYPTION_KEY=${fnOld.ENCRYPTION_KEY || randomBytes(32).toString('hex')}`,
  '# Real key: generate/tailor call the Anthropic API and cost money.',
  `ANTHROPIC_API_KEY=${anthropicKey}`,
  "# The website ATS checker's own key (#278). Unset: the page falls back to its word list.",
  keep('ANTHROPIC_CHECKER_API_KEY'),
  "# The checker's Turnstile secret (#278). Unset: no bot check. Cloudflare's test secret 1x0000000000000000000000000000000AA always passes.",
  keep('TURNSTILE_SECRET_KEY'),
  "# Hosts a Turnstile token may come from. Production leaves it unset (cover-me.dev only).",
  `TURNSTILE_HOSTNAMES=${fnOld.TURNSTILE_HOSTNAMES || 'localhost,127.0.0.1'}`,
  '# Logs resume text and prompts to the function logs. Local only.',
  `DEBUG_MODE=${fnOld.DEBUG_MODE || 'false'}`,
  '# Local Stripe checkout (billing function): test-mode values from the sandbox account.',
  ...STRIPE_FN_KEYS.map((k) => fnOld[k] ? `${k}=${fnOld[k]}` : `# ${k}=`),
  '# Checkout and the billing portal return here (billing falls back to production).',
  'SITE_URL=http://localhost:3100',
])
if (!anthropicKey) console.warn('  ANTHROPIC_API_KEY is empty: add one to use generate/tailor from the extension.')

// Accept the spellings the Supabase CLI's parser treats as on: quotes, a trailing
// comment, TRUE or 1 (#16).
const googleOn = (readEnv(join(BACKEND, '.env')).SUPABASE_AUTH_EXTERNAL_GOOGLE_ENABLED ?? '')
  .replace(/\s+#.*$/, '').trim().replace(/^(["'])(.*)\1$/, '$2').toLowerCase()
const google = googleOn === 'true' || googleOn === '1' ? '1' : ''

write(join(REPO, 'extension', '.env.localdb'), [
  '# Points the extension at the local Supabase stack. Generated by `pnpm env:local` in backend/.',
  `VITE_SUPABASE_URL=${API_URL}`,
  `VITE_SUPABASE_PUBLISHABLE_KEY=${publishableKey(status)}`,
  'VITE_WEB_URL=http://localhost:3100',
  `VITE_GOOGLE_SIGNIN=${google}`,
])

const webPath = join(REPO, 'web', '.env.localdb')
const webOld = readEnv(webPath)
write(webPath, [
  '# Points the web app at the local Supabase stack. Generated by `pnpm env:local` in backend/.',
  '# Stripe keys still come from .env.local (use test-mode keys).',
  `NEXT_PUBLIC_SUPABASE_URL=${API_URL}`,
  `NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=${publishableKey(status)}`,
  `SUPABASE_SERVICE_KEY=${serviceKey(status)}`,
  'NEXT_PUBLIC_SITE_URL=http://localhost:3100',
  `NEXT_PUBLIC_GOOGLE_SIGNIN=${google}`,
  '# whsec_... from `stripe listen --print-secret` with your test key pinned (README → Local backend).',
  // Left commented until set: an empty value would override .env.local's (https://github.com/TheLinc/cover-me/commit/f2256d02).
  webOld.STRIPE_WEBHOOK_SECRET ? `STRIPE_WEBHOOK_SECRET=${webOld.STRIPE_WEBHOOK_SECRET}` : '# STRIPE_WEBHOOK_SECRET=',
  "# The ATS checker's Turnstile site key (#278). Set it with the functions' TURNSTILE_SECRET_KEY, or leave both unset. Test key: 1x00000000000000000000BB.",
  webOld.NEXT_PUBLIC_TURNSTILE_SITE_KEY ? `NEXT_PUBLIC_TURNSTILE_SITE_KEY=${webOld.NEXT_PUBLIC_TURNSTILE_SITE_KEY}` : '# NEXT_PUBLIC_TURNSTILE_SITE_KEY=',
])
